#!/usr/bin/env bash
# Verification for the issue-flow engine, milestone K6 — the release gates
# (design: design/guild/23-engine/design.md §10.2 release gates, §9.5, §10.4, §10.5; k6-notes.md).
#
# Runs the Python unittest modules tests/engine/test_k6_*.py — the offline part of the K6 gate items
# (review-k5-r12 "K6 이월"): registered blind wordings (44), an answer belongs to the run that asked (33, 40), grounds for an option that cannot run (39), unverified groups (4), gated groups from the §9.5 table + every table question blind (27, 43), the escalation cap (14), cross-version resume (17), grader evidence · quality rules · dual judgment (11), tripwire centres from the replay (18), the label audit calibration (29, 1), the review-k6-r1 fixes (test_k6_r1: safe answers, after-reveal, release paths, grader AC, blind labels, the 0.101.3 folds' readers …) and the review-k6-r2 fixes (test_k6_r2: inherent gate groups released by sheet verdicts, the sealed KICKOFF footprint, scope asides, the remote judgment, open candidates across scopes, dual judgment before the question, engine-env not folded) and the review-k6-r3 fixes (test_k6_r3: the person's KICKOFF reading carried as the reading, Issue-wide sealing incl. STAKES irreversible, scope over product nouns, directory areas as irreversible, numeric ratings, one INHERENT verdict per decision, reconciled open candidates, inherent rows with evidence, code spans) and the review-k6-r4 fixes with the scope reduction (test_k6_r4: KICKOFF / STAKES asked openly and released by grading-sheet verdicts, the sealing code gone, the person's reading judged by content, the latest of two reading answers carried and a `reask` way out, re-keyed capture footprints, a true superset, source-scoped asides refused, code-span ratings, an unread log never reconciled) and the review-k6-r5 fixes (test_k6_r5: the person's reading taken by a fixed engine id — never by text closeness, opposite scopes never taken —, `reask` questions never sheet rows, no capture area lost to the value cap, source-scope refusal by the act of reference, rating words in code spans, the taking judge's footprint joined, a person's way out for a candidate whose log is gone) and the review-k6-r6 fixes (test_k6_r6: two exact-equality refutations of taking the person's reading, the way out only for an unread candidate and a re-listed drop revoking the release, a bounded pending block, rating words in any case or identifier piece and the act of asking as a reference) and the review-k6-r7 fixes (test_k6_r7: a prefix only for a summary stored cut and the pause naming its refutation, one rating list read beside scope words, a head-only reading's tail kept as ancestor directories, any dev grade re-checking human drops, upper-case / camelCase / joined-span / scope-reference label gaps, the verification gate writer gate_report.py) and the review-k6-r8 fixes (test_k6_r8) and the review-k6-r9 fixes (test_k6_r9: gate_report rows checked against each other — replay only for a group with no planned synthetic set, the Issue as the split unit, `issue/D-id` ids, one group per id, kind / group conflicts, tuning rows required; hyphenated rating compounds in whole labels; per-call fsafe temp names) and the review-k6-r10 fixes (test_k6_r10: one held-out set — the copies of an id by their worst verdict, `pass` never counted; the compound-noun exception removed (r7 rule); tuning Issues from every tuning row; short temp names for fsafe / journal / settings; the shared gates export race; runners counting ran − skipped) and the review-k6-r11 fixes (test_k6_r11: synthetic only for a group the input has no replay row for — old held-out rows as `retired`; a failed gates export leaves no temp tree; runner keys not misread from "expected failures=") and the review-k6-r12 fixes (test_k6_r12: group names case-insensitive and an unknown replay group closing every synthetic path, the reports on stdout; a raising extraction leaves no temp tree) and the review-k6-r13 fixes (test_k6_r13: no synthetic verification without replay tuning rows, non-object rows rejected, every report on stdout; judgment names are unknown groups) and the 0.102.15 fixes (test_k6_0102_15: result.json allow shape, never behind a symlinked parent, pnpm fetch / offline install, runner missing, turbo summaries, single-role format rebaseline, visual unsure) and the 0.102.5 patch after the word_app #1945 runs (test_k6_0102_5: base merges accepted and other drift asked accept/stop, one automatic developer retry on a recurring blocker, a flaky suite's ≤ 2 failing tests re-run once, an unsure code check never a gap, the effective check running the real app tests, a remote ref deleted elsewhere no violation, unverified groups graded after instead of asked) and the review-0102-5 fixes (test_k6_0102_6: a flake needs a green whole-suite re-run and every counted failure named, security decisions asked from the real briefs, base merges checked against the engine's base and git's clean merge, a drift accept bound to what the question showed, remote rewinds and non-PR branch deletions as violations again, every cited test of an AC reacting and exact full test names, flake notes and unsure checks as grading-sheet rows, the irreversible KICKOFF mark, the stagnation hint across a crash-resume) and the review-0102-6 fixes (test_k6_0102_7: security read from the judges' structured security_concern in any language, issue phrases only as the text trigger, a group drift question bound to its own snapshot with every item on the block, no doubled PR title prefix, every code grade-trigger block a sheet row, the narrowest nested KICKOFF reading taken without a person, the auditor's own out/ writable and a concerned auditor with valid findings an audit) and the review-0102-7 fixes (test_k6_0102_8: a STAKES security concern never auto-narrowed, EX-ARB's developer route under a security concern to a person, an auditor concern other than the refused result write dispatched again then asked, every post-hoc group carrying security_concern, the text trigger's false positives and negatives, the EX-ARB security BLOCKER rule under the unverified coercion, the PR title prefix without a space or with a full-width colon, auto-narrow only for the reading choice with the Issue's AC checked and what it removed recorded, follow-ups without design output) and the review-0102-8 fixes (test_k6_0102_9: the Issue-AC check strict and verbatim on the real word_app #1797 body — broad AC-section titles, top-level items only, an unread AC section never auto-narrowed —, an unverified KICKOFF's grading row naming the Issue AC kept / dropped, the text trigger's mobile-permission / show-password / design-token false positives and log-output / other-user false negatives, the auditor's own run dir's result file only, an EX-ARB finding marked security under a top-level false) and the word_app #1797 loop-back-cap fixes (test_k6_0102_9 R1797*: one id set for the TEST judge, covers and checks — cases folded into the AC they name —, an assertion inside a same-file helper of a golden test, an unsure check carrying its reason, no loop-back that repeats an earlier one without a test change) and the review-0102-9 fixes (test_k6_0102_10: every case folded into an AC keeps its own cover check — an AC with no cover is a gap, an uncovered case of a covered AC a grading row, a case's weaker verdict kept —, a helper assertion only from a top-level unconditional call ≤ 2 deep and a real matcher, an AC section read whole or asked, no unchanged_since early stop, no security text trigger, a regression guard beside a reacting test no grading row) and the review-0102-10 fixes (test_k6_0102_11: the analysis AC list and every AC test-cases.md names judged — word_app #1945's AC #4 / #5 —, an untestable AC with a reason a grading row, a cover only when its test file and name are in the tree, a new test that does not react unsure again, sub-labels inside an AC section read, a read-only role's writes put back and QA's a fixable finding — word_app #1797's release notes —, the loop-back cap per source under a total of 3 with a `reset` answer and an id-mapping gap an engine defect, helper calls in a literal for / runAsync), see k6-notes.md for the full list.
# No test calls `claude`, a model or GitHub (a failing `gh` is first on PATH).
#
# Usage: bash plugins/guild-plugin/tests/engine_k6_test.sh
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ENGINE="$HERE/../skills/gld/engine/gld_engine.py"
[ -f "$ENGINE" ] || { echo "missing: $ENGINE" >&2; exit 1; }
PY="${PY:-python3}"

gld_skip() { echo "SKIP: $1" >&2; [ "${GLD_ALLOW_SKIP:-0}" = 1 ] && exit 0; \
            echo "FAIL  스킵은 통과가 아닙니다 — GLD_ALLOW_SKIP=1 로 명시하십시오." >&2; exit 1; }
"$PY" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)' 2>/dev/null \
  || gld_skip "$PY is not Python 3.9+ — the engine's floor"
command -v git >/dev/null 2>&1 || gld_skip "git is not installed"

WORK="$(mktemp -d)" || { echo "mktemp -d failed" >&2; exit 1; }
trap 'chmod -R u+w "$WORK" 2>/dev/null; rm -rf "$WORK"' EXIT
OUT="$WORK/unittest.out"
( cd "$HERE/engine" && PYTHONDONTWRITEBYTECODE=1 TMPDIR="$WORK" "$PY" -W ignore::ResourceWarning \
    -m unittest discover -s . -p 'test_k6_*.py' -v ) >"$OUT" 2>&1
RC=$?
grep -E '\.\.\. (ok|FAIL|ERROR|skipped)' "$OUT" | sed -E 's/^(.*) \.\.\. ok$/  PASS  \1/; s/^(.*) \.\.\. (FAIL|ERROR)$/  FAIL  \1/; s/^(.*) \.\.\. skipped.*$/  SKIP  \1/'
if [ "$RC" -ne 0 ]; then
  sed -n '/^======/,$p' "$OUT"
fi
# review-k6-r10 m3: count from unittest's own summary — `Ran N` minus the skipped tests (a skip is not a pass), and the
# failures + errors of its `FAILED (...)` line. A line a test splits by printing mid-line (r9: a SyntaxWarning, a
# thread's traceback) no longer drops a test from the count, and a test turned into a skip lowers it.
RAN=$(sed -nE 's/^Ran ([0-9]+) tests? in .*/\1/p' "$OUT" | tail -1); RAN=${RAN:-0}
SUMMARY=$(grep -E '^(OK|FAILED)( \(.*\))?$' "$OUT" | tail -1)
SKIPPED=$(printf '%s' "$SUMMARY" | sed -nE 's/.*(\(|, )skipped=([0-9]+).*/\2/p'); SKIPPED=${SKIPPED:-0}
FAILURES=$(printf '%s' "$SUMMARY" | sed -nE 's/.*(\(|, )failures=([0-9]+).*/\2/p'); FAILURES=${FAILURES:-0}
ERRORS=$(printf '%s' "$SUMMARY" | sed -nE 's/.*(\(|, )errors=([0-9]+).*/\2/p'); ERRORS=${ERRORS:-0}
COUNTED=$((RAN - SKIPPED))
FAIL=$((FAILURES + ERRORS))
PASS=$((COUNTED - FAIL))
[ -n "$SUMMARY" ] || { FAIL=$((FAIL + 1)); echo "FAIL  unittest 요약 줄(OK / FAILED)이 없습니다."; }
echo "engine K6: $PASS passed, $FAIL failed (ran $RAN, skipped $SKIPPED)"
# ⚠ Keep equal to the measured count (ran − skipped); raise it only when tests are added on purpose.
ENGINE_K6_MIN_TESTS=726
if [ "$COUNTED" -lt "$ENGINE_K6_MIN_TESTS" ]; then
  echo "FAIL  실행된 검사가 ${COUNTED}건뿐입니다 (스킵 제외, 최소 ${ENGINE_K6_MIN_TESTS}건)."
  exit 1
fi
[ "$RC" -eq 0 ] && [ "$FAIL" -eq 0 ]
